      </section>

      @if (inv.status === 'DRAFT') {
        <form [formGroup]="discountForm" (ngSubmit)="applyDiscount()" data-testid="discount-form" novalidate>
          <h2>Discount</h2>
          <div>
            <label for="discount-pct">Percentage off the subtotal</label>
            <input
              id="discount-pct"
              type="number"
              inputmode="decimal"
              min="0"
